def get_chemotherapy_priority(patient):
    """
    Compute the chemotherapy priority of the patient.
    patient: A patient object with attributes: duration_of_condition, age, symptoms, insurance status (insured, underinsured, uninsured), severity, comorbidities, resource_availability
    """
    # Initial priority score
    score = 0

    # Increase priority for severe symptoms
    if 'chronic pain' in patient.symptoms or 'reduced mobility' in patient.symptoms or 'ongoing fatigue' in patient.symptoms:
        score += 2
    else:
        score += 1

    # Increase priority for longer duration of condition
    if patient.duration_of_condition > 90:
        score += 3
    elif 71 <= patient.duration_of_condition <= 90:
        score += 2
    elif patient.duration_of_condition <= 70:
        score += 1

    if patient.severity >= 7:
        # Increase priority for severe conditions
        score += 3
    elif patient.severity >= 4:
        # Medium severity score
        score += 2
    else:
        # Mild severity score
        score += 1

    # Increase priority for older patients and patients with many comorbidities
    if patient.age > 50 or patient.comorbidities >= 3:
        score += 2
    elif patient.age > 40 or patient.comorbidities >= 2:
        score += 1

    # Increase priority for uninsured patients
    if patient.insurance_status == "uninsured":
        score += 2

    # Check if the patient has resources availability and increase priority accordingly
    if patient.resource_availability:
        score += 1

    return score

